import fs from "node:fs";

// Home + header NDC. Applique : toutes les sections editables via WordPress
// (homeFields, Polylang gere : page EN via lien de traduction), bandeau
// certifications/Altarea, bouton brochure (modale + email) sur la home, header
// avec menu deroulant "A propos de nous" (equipes + groupe) et boutons Contact
// / Portail Client mis en valeur.

const files = {
  "app/[locale]/page.tsx": "",
  "app/globals.css": "",
  "messages/fr.json": "",
  "messages/en.json": "",
  "components/CertBanner.tsx": "",
  "components/FaqSection.tsx": "",
  "components/FaqHome.tsx": "",
  "components/SiteHeader.tsx": "",
  "components/BrochureButton.tsx": "",
  "lib/wordpress.ts": "",
  "wordpress/homeFields.json": "",
};

for (const [path, b64] of Object.entries(files)) {
  const dir = path.split("/").slice(0, -1).join("/");
  if (dir) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path, Buffer.from(b64, "base64").toString("utf8"));
  console.log("ecrit :", path);
}
if (fs.existsSync("components/Credibility.tsx")) {
  fs.unlinkSync("components/Credibility.tsx");
  console.log("supprime : components/Credibility.tsx");
}
console.log("\n✓ Fait. Commit + push vers ton depot -> Vercel redeploiera.");
